def pick(paths):
    found=[p for p in paths if p.is_dir()]
    if len(found)!=1: raise FileNotFoundError(f"Expected exactly one fixed input: {paths}; found {found}")
    return found[0]
source=pick([Path('/kaggle/input/datasets/tumis001/rsna-cnn-topk-support-source-v1/skanee'),Path('/kaggle/input/rsna-cnn-topk-support-source-v1/skanee')])
