modules={'build_native_triplet_cache.py': '"""Build deduplicated native-neighbor slices; shared preprocessing for inference.\n\nRequires the pinned baseline source on PYTHONPATH. No GPU or label inference.\nEach committed part contains complete studies; manifest replacement is atomic.\n"""\nimport argparse\nimport csv\nimport hashlib\nimport json\nimport os\nimport time\nfrom pathlib import Path\n\nimport numpy as np\nfrom src.features.dicom import decode_pixels, normalized_positions, read_series, series_bounds, slice_normal\nfrom src.images.prepare import physical_crop_with_support, pixel_spacing, select_series, select_slice_indices, to_uint8\nfrom src.reports.schema import TARGETS\nfrom local_global_data import SCHEMA\n\n\ndef triplets(centres, count):\n    centres = np.asarray(centres, dtype=np.int64)\n    return np.clip(centres[:, None] + np.array([-1, 0, 1]), 0, count - 1)\n\n\ndef acquisition_metadata(dicom, job):\n    normal = slice_normal(dicom)\n    plane = None\n    if normal is not None and np.max(np.abs(normal)) >= 0.8:\n        plane = ("Sagittal", "Coronal", "Axial")[np.argmax(np.abs(normal))]\n    fat = job.get("fat_suppression")\n    if str(fat) not in ("0", "1"):\n        # Missing FS tags are unknown, not proof that fat was not suppressed.\n        options = getattr(dicom, "ScanOptions", [])\n        options = [options] if isinstance(options, str) else list(options)\n        suppression = str(getattr(dicom, "SpectrallySelectedSuppression", "")).upper()\n        fat = "1" if "FS" in options or suppression == "FAT" else ("0" if suppression == "NONE" else None)\n    return {"plane": plane, "reported_plane": job.get("plane"), "fat_suppression": fat}\n\n\ndef prepare_slot(job, cache):\n    import pydicom\n    ordered = read_series(Path(job["folder"]))\n    size = cache["image_size"]\n    empty = np.zeros((0, size, size), dtype=np.uint8)\n    record = {**{k: job.get(k) for k in ("study_id", "series_id", "slot", "plane", "fluid_sensitive", "fat_suppression")},\n              "schema": SCHEMA, "order_source": ordered.order_source, "exceptions": ordered.exceptions,\n              "decode_errors": 0, "count": 0, "stored_count": 0, "positions": [], "triplet_offsets": [],\n              "center_indices": [], "native_indices": [], "files": [], "center_files": [],\n              "neighbor_gaps_mm": [], "spacing_mm": None}\n    if ordered.order_source in cache["exclude_order_sources"] or not ordered.files:\n        return record, empty, empty\n    centres = select_slice_indices(len(ordered.files), cache["slices_per_slot"], *cache["central_band"])\n    indices = np.unique(triplets(centres, len(ordered.files)))\n    decoded = {}\n    spacing, first = None, None\n    for index in indices:\n        try:\n            d = pydicom.dcmread(ordered.files[index])\n            pixels = decode_pixels(d)\n            if pixels.ndim != 2:\n                raise ValueError("Expected 2D DICOM slice")\n            decoded[int(index)] = (pixels, getattr(d, "PhotometricInterpretation", "") == "MONOCHROME1")\n            # Match baseline spacing reference: first successful selected centre.\n            if index in centres and first is None:\n                first, spacing = d, pixel_spacing(d)\n        except Exception:\n            record["decode_errors"] += 1\n    centres = [i for i in centres if i in decoded]\n    if not centres:\n        return record, empty, empty\n    mapping = triplets(centres, len(ordered.files))\n    indices = np.unique(mapping)\n    row_of_index = {int(v): i for i, v in enumerate(indices)}\n    # Preserve the original percentile reference, NOT all newly decoded neighbors.\n    low, high = series_bounds([decoded[i][0] for i in centres], *cache["clip_percentiles"])\n    images, masks = [], []\n    for index in indices:\n        if int(index) not in decoded:\n            images.append(np.zeros((size, size), dtype=np.uint8))\n            masks.append(np.zeros((size, size), dtype=np.uint8))\n            continue\n        pixels, inverted = decoded[int(index)]\n        support = np.isfinite(pixels)\n        image = to_uint8(pixels, low, high, inverted)\n        image[~support] = 0\n        image, support = physical_crop_with_support(image.astype(np.float32), support, spacing,\n                                                    cache["field_of_view_mm"], size)\n        images.append(image.round().astype(np.uint8)); masks.append(support)\n    positions = normalized_positions(ordered.coordinates)\n    coords = np.asarray(ordered.coordinates)\n    gaps = np.abs(coords[mapping[:, [0, 2]]] - coords[np.asarray(centres), None])\n    if ordered.order_source != "physical":\n        gaps[:] = 0  # InstanceNumber differences are not millimetres.\n    record.update(acquisition_metadata(first, job))\n    record.update(count=len(centres), stored_count=len(indices), positions=[positions[i] for i in centres],\n                  triplet_offsets=[[row_of_index[int(v)] for v in row] for row in mapping],\n                  center_indices=centres, native_indices=indices.tolist(),\n                  files=[ordered.files[i].name for i in indices], center_files=[ordered.files[i].name for i in centres],\n                  neighbor_gaps_mm=gaps.tolist(), spacing_mm=list(spacing) if spacing else None,\n                  clip_bounds=[low, high], missing_native_indices=[int(i) for i in indices if int(i) not in decoded])\n    return record, np.stack(images), np.stack(masks)\n\n\nclass SlotDataset:\n    def __init__(self, jobs, cache): self.jobs, self.cache = jobs, cache\n    def __len__(self): return len(self.jobs)\n    def __getitem__(self, index): return prepare_slot(self.jobs[index], self.cache)\n\n\ndef read_csv(path):\n    with path.open(newline="", encoding="utf-8-sig") as f: return list(csv.DictReader(f))\n\n\ndef atomic_json(path, value):\n    temp = path.with_suffix(path.suffix + ".tmp")\n    temp.write_text(json.dumps(value, indent=2, allow_nan=False) + "\\n")\n    temp.replace(path)\n\n\ndef main():\n    p = argparse.ArgumentParser()\n    p.add_argument("--data-root", type=Path, required=True)\n    p.add_argument("--config", type=Path, required=True)\n    p.add_argument("--output-dir", type=Path, required=True)\n    p.add_argument("--split", choices=["train", "test"], default="train")\n    p.add_argument("--shard-index", type=int, default=0)\n    p.add_argument("--shard-count", type=int, default=4)\n    p.add_argument("--workers", type=int, default=4)\n    p.add_argument("--studies-per-part", type=int, default=50)\n    p.add_argument("--time-budget-hours", type=float, default=10.5)\n    a = p.parse_args()\n    if not 0 <= a.shard_index < a.shard_count: raise ValueError("Invalid shard")\n    import torch\n    torch.set_num_threads(1)\n    started = time.monotonic()\n    config = json.loads(a.config.read_text()); cache = config["cache"]\n    out = a.output_dir; out.mkdir(parents=True, exist_ok=True)\n    manifest_path = out / "manifest.jsonl"\n    records = [json.loads(s) for s in manifest_path.read_text().splitlines() if s] if manifest_path.is_file() else []\n    identity = {"schema": SCHEMA, "config_sha256": hashlib.sha256(a.config.read_bytes()).hexdigest(),\n                "shard": [a.shard_index, a.shard_count], "split": a.split}\n    identity_path = out / "identity.json"\n    if identity_path.exists() and json.loads(identity_path.read_text()) != identity: raise ValueError("Existing cache identity mismatch")\n    atomic_json(identity_path, identity)\n    studies = read_csv(a.data_root / f"{a.split}.csv")\n    if a.split == "train": studies = [r for r in studies if not all(r.get(t, "") in {"0", "1"} for t in TARGETS)]\n    expected = sorted(r["StudyInstanceUID"] for r in studies if int(hashlib.sha256(r["StudyInstanceUID"].encode()).hexdigest(), 16) % a.shard_count == a.shard_index)\n    done = {r["study_id"] for r in records}\n    if not done.issubset(expected): raise ValueError("Manifest has unexpected studies")\n    by_study = {}\n    for r in read_csv(a.data_root / f"{a.split}_series.csv"): by_study.setdefault(r["StudyInstanceUID"], []).append(r)\n    jobs = []\n    for sid in expected:\n        if sid in done: continue\n        selected = select_series(by_study.get(sid, []), cache["series_slots"])\n        if not selected: raise ValueError(f"No selected series: {sid}")\n        for slot, r in enumerate(selected):\n            jobs.append({"study_id": sid, "series_id": r["SeriesInstanceUID"], "slot": slot,\n                         "folder": str(a.data_root / f"{a.split}_series" / sid / r["SeriesInstanceUID"]),\n                         "plane": r.get("Anatomical_Plane"), "fluid_sensitive": r.get("Fluid_Sensitive"),\n                         "fat_suppression": r.get("Fat_Suppression")})\n    print(f"NATIVE_CACHE shard={a.shard_index}/{a.shard_count} expected={len(expected)} jobs={len(jobs)}", flush=True)\n    # conversion to numpy in the parent avoids shared float tensor buffers.\n    loader = torch.utils.data.DataLoader(SlotDataset(jobs, cache), batch_size=None, num_workers=a.workers,\n                                        collate_fn=lambda x: x, prefetch_factor=1 if a.workers else None)\n    part_index = 1 + max([int(r["part"].split("_")[1].split(".")[0]) for r in records], default=-1)\n    pending, images, masks, stored, current = [], [], [], 0, None\n\n    def flush():\n        nonlocal pending, images, masks, stored, part_index, records\n        if not pending: return\n        names = [f"{kind}_{part_index:03d}.npy" for kind in ("slices", "support")]\n        for name, buffers in zip(names, (images, masks)):\n            # Disk-backed concatenation bounds RAM to the buffered input arrays.\n            temp = out / (name + ".tmp")\n            array = np.lib.format.open_memmap(temp, mode="w+", dtype=np.uint8, shape=(stored, cache["image_size"], cache["image_size"]))\n            row = 0\n            for block in buffers: array[row:row + len(block)] = block; row += len(block)\n            array.flush(); del array\n            temp.replace(out / name)\n        new = [{**r, "part": names[0], "support_part": names[1]} for r in pending]\n        temp = manifest_path.with_suffix(".jsonl.tmp")\n        with temp.open("w") as f:\n            for r in records + new: f.write(json.dumps(r, allow_nan=False) + "\\n")\n            f.flush(); os.fsync(f.fileno())\n        temp.replace(manifest_path)\n        records += new\n        print(f"COMMITTED part={part_index} studies={len({r[\'study_id\'] for r in records})}/{len(expected)} stored={stored}", flush=True)\n        pending, images, masks, stored = [], [], [], 0; part_index += 1\n\n    for r, x, support in loader:\n        if r["study_id"] != current:\n            if time.monotonic() - started > a.time_budget_hours * 3600: break\n            if len({item["study_id"] for item in pending}) >= a.studies_per_part: flush()\n            current = r["study_id"]\n        r["row_start"] = stored\n        pending.append(r); images.append(x); masks.append(support); stored += len(x)\n    flush()\n    complete = {r["study_id"] for r in records} == set(expected)\n    summary = {**identity, "cache": cache, "complete": complete, "studies": len({r["study_id"] for r in records}),\n               "windows": sum(r["count"] for r in records), "stored_slices": sum(r["stored_count"] for r in records),\n               "decode_errors": sum(r["decode_errors"] for r in records), "seconds": time.monotonic() - started}\n    atomic_json(out / "cache_summary.json", summary)\n    print(json.dumps(summary), flush=True)\n    if not complete: raise RuntimeError("Cache incomplete; resume from committed full studies")\n\n\nif __name__ == "__main__": main()\n', 'local_global_data.py': '"""Native-neighbor cache and selected-window batches shared by train and inference."""\nfrom dataclasses import dataclass\nfrom pathlib import Path\n\nimport numpy as np\nimport torch\nimport torch.nn.functional as F\n\nSCHEMA = "native_triplets_v1"\nMAX_WINDOWS = 48\nMEAN, STD = 0.449, 0.226\n# Runner chooses these only after the same-GPU timing/memory preflight.\nEXECUTION = {"augment_on_gpu": False, "channels_last": False}\n\n\ndef category(value, choices):\n    value = str(value).strip().lower()\n    return choices.index(value) if value in choices else len(choices)\n\n\ndef window_metadata(record):\n    """Coordinates are relative to their own series, never aligned across planes."""\n    n = record["count"]\n    plane = category(record.get("plane"), ["sagittal", "coronal", "axial"])\n    fluid = category(record.get("fluid_sensitive"), ["0", "1"])\n    fat = category(record.get("fat_suppression"), ["0", "1"])\n    geometry = record["order_source"] == "physical"\n    position = np.asarray(record["positions"], dtype=np.float32)\n    gaps = np.asarray(record["neighbor_gaps_mm"], dtype=np.float32)\n    if position.shape != (n,) or gaps.shape != (n, 2):\n        raise ValueError("Metadata and centre counts differ")\n    # Four categorical fields and eight numerical fields. Unknown geometry has\n    # zero gap encodings plus an explicit availability indicator.\n    phases = np.pi * position\n    numeric = np.column_stack((position * 2 - 1, np.sin(phases), np.cos(phases),\n                               np.sin(2 * phases), np.cos(2 * phases),\n                               np.log1p(gaps[:, 0]), np.log1p(gaps[:, 1]),\n                               np.full(n, float(geometry)))).astype(np.float32)\n    discrete = np.tile([plane, fluid, fat, record["slot"]], (n, 1)).astype(np.float32)\n    result = np.column_stack((discrete, numeric))\n    if not np.isfinite(result).all() or (gaps < 0).any():\n        raise ValueError("Invalid position/gap metadata")\n    return result\n\n\nclass NativeStudyCache:\n    """Select centres before materializing triplets; mmap unique slices once."""\n    def __init__(self, manifest):\n        self.manifest = manifest\n        self._parts = {}\n        self.records = {}\n        for sid, rows in manifest.items():\n            rows = sorted(rows, key=lambda r: r["slot"])\n            for r in rows:\n                if r.get("schema") != SCHEMA:\n                    raise ValueError("Native acquired-neighbor cache required; old cache is incompatible")\n                mapping = np.asarray(r["triplet_offsets"], dtype=np.int64)\n                if mapping.shape != (r["count"], 3) or mapping.min() < 0 or mapping.max() >= r["stored_count"]:\n                    raise ValueError("Invalid triplet row mapping")\n            self.records[sid] = (rows, np.cumsum([0] + [r["count"] for r in rows]),\n                                 np.concatenate([window_metadata(r) for r in rows]))\n\n    def part(self, directory, name):\n        key = (directory, name)\n        if key not in self._parts:\n            self._parts[key] = np.load(Path(directory) / name, mmap_mode="r")\n        return self._parts[key]\n\n    def selected(self, sid, keep):\n        rows, boundaries, metadata = self.records[sid]\n        images, supports = [], []\n        for i, r in enumerate(rows):\n            local = keep[(keep >= boundaries[i]) & (keep < boundaries[i + 1])] - boundaries[i]\n            if not len(local):\n                continue\n            offsets = np.asarray(r["triplet_offsets"], dtype=np.int64)[local] + r["row_start"]\n            images.append(self.part(r["directory"], r["part"])[offsets])\n            supports.append(self.part(r["directory"], r["support_part"])[offsets])\n        # Caller supplies sorted indices; row ordering remains slot-major.\n        return np.concatenate(images), np.concatenate(supports), metadata[keep]\n\n\n@dataclass\nclass WindowBatch:\n    images: torch.Tensor\n    metadata: torch.Tensor\n    padded_indices: torch.Tensor\n    valid: torch.Tensor\n\n\ndef augment_images(images, owners, studies, rng, settings):\n    """Baseline random draws; transform intensity and support together.\n\n    No CUDA-to-CPU queries or full-size erasing masks. Mask geometry uses nearest\n    interpolation; intensity uses bilinear. Erasing applies only to intensities.\n    """\n    device = images.device\n    area = rng.uniform(settings["crop_area_min"], 1.0, studies)\n    extent = np.sqrt(area)\n    angles = np.radians(rng.uniform(-settings["rotation_degrees"], settings["rotation_degrees"], studies))\n    margin = (1 - extent) + settings.get("translate_fraction", 0.0)\n    ox = rng.uniform(-1, 1, studies) * margin\n    oy = rng.uniform(-1, 1, studies) * margin\n    theta = np.zeros((studies, 2, 3), dtype=np.float32)\n    theta[:, 0, 0] = theta[:, 1, 1] = np.cos(angles) * extent\n    theta[:, 0, 1], theta[:, 1, 0] = -np.sin(angles) * extent, np.sin(angles) * extent\n    theta[:, 0, 2], theta[:, 1, 2] = ox, oy\n    grid = F.affine_grid(torch.as_tensor(theta, device=device)[owners], images.shape, align_corners=False)\n    intensity = F.grid_sample(images[:, :3], grid, mode="bilinear", align_corners=False)\n    support = F.grid_sample(images[:, 3:], grid, mode="nearest", align_corners=False)\n    gain = torch.as_tensor(rng.uniform(1 - settings["intensity_jitter"], 1 + settings["intensity_jitter"], studies), dtype=torch.float32, device=device)\n    shift = torch.as_tensor(rng.uniform(-settings["brightness_shift"], settings["brightness_shift"], studies), dtype=torch.float32, device=device)\n    intensity.mul_(gain[owners, None, None, None]).add_(shift[owners, None, None, None])\n    erase = rng.random(len(images)) < settings["erase_probability"]\n    side = int(round(images.shape[-1] * settings["erase_fraction"]))\n    for i in np.flatnonzero(erase):\n        top, left = (int(rng.integers(0, images.shape[-1] - side)) for _ in range(2))\n        intensity[i, :, top:top + side, left:left + side] = 0\n    return torch.cat((intensity, support), dim=1)\n\n\ndef prepare_batch(cache, labels, study_ids, slice_cap, rng, device, augmentation=None, sources=None):\n    pixels, metadata, owners, padded, targets, weights = [], [], [], [], [], []\n    valid = np.zeros((len(study_ids), MAX_WINDOWS), dtype=bool)\n    for i, sid in enumerate(study_ids):\n        n = len(cache.records[sid][2])\n        if not 0 < n <= MAX_WINDOWS:\n            raise ValueError(f"Invalid centre count for {sid}: {n}")\n        keep = np.arange(n)\n        if slice_cap is not None and n > slice_cap:\n            keep = (np.sort(rng.choice(n, slice_cap, replace=False)) if rng is not None\n                    else np.linspace(0, n - 1, slice_cap).round().astype(int))\n        images, support, meta = cache.selected(sid, keep)\n        pixels.append(np.concatenate((images, support), axis=1))\n        metadata.append(meta)\n        owners.extend([i] * len(keep))\n        padded.extend(i * MAX_WINDOWS + np.arange(len(keep)))\n        valid[i, :len(keep)] = True\n        targets.append(labels[sid][0]); weights.append(labels[sid][1])\n    # Keep uint8 until transfer: 4x smaller host buffer and PCIe transfer than\n    # moving float32. No extra prefetched batch or permanent device cache.\n    host = torch.from_numpy(np.concatenate(pixels))\n    if device.type == "cuda":\n        host = host.pin_memory()\n    processing_device = device if EXECUTION["augment_on_gpu"] else torch.device("cpu")\n    images = host.to(processing_device, non_blocking=True).float()\n    images[:, :3].div_(255).sub_(MEAN).div_(STD)\n    images[:, 3:].div_(255)\n    owner = torch.tensor(owners, dtype=torch.long, device=processing_device)\n    if rng is not None:\n        images = augment_images(images, owner, len(study_ids), rng, augmentation)\n    images = images.to(device, non_blocking=True)\n    if EXECUTION["channels_last"]:\n        images = images.contiguous(memory_format=torch.channels_last)\n    owner = owner.to(device)\n    batch = WindowBatch(images, torch.as_tensor(np.concatenate(metadata), device=device),\n                        torch.tensor(padded, device=device), torch.as_tensor(valid, device=device))\n    return (batch, owner, torch.as_tensor(np.stack(targets), device=device),\n            torch.as_tensor(np.stack(weights), device=device),\n            torch.as_tensor(np.stack([sources[s] for s in study_ids]), device=device) if sources else None,\n            torch.ones(len(owners), device=device))\n', 'local_global_model.py': '"""One ResNet50 pass: native local triplets and study-wide contextual correction."""\nimport math\nimport torch\nfrom local_global_data import MAX_WINDOWS, WindowBatch\n\n\nclass SliceModel(torch.nn.Module):\n    def __init__(self, backbone, pretrained, dropout, targets, top_k_fraction=0.1):\n        super().__init__()\n        import torchvision\n        if backbone != "resnet50":\n            raise ValueError("This experiment is pinned to ResNet50")\n        self.backbone = torchvision.models.resnet50(weights="DEFAULT" if pretrained else None)\n        old = self.backbone.conv1\n        self.backbone.conv1 = torch.nn.Conv2d(6, 64, 7, stride=2, padding=3, bias=False)\n        with torch.no_grad():\n            self.backbone.conv1.weight.zero_()\n            self.backbone.conv1.weight[:, :3].copy_(old.weight)\n        features = self.backbone.fc.in_features\n        self.backbone.fc = torch.nn.Identity()\n        self.head = torch.nn.Sequential(torch.nn.Dropout(dropout), torch.nn.Linear(features, targets))\n        width = 256\n        self.projection = torch.nn.Linear(features, width)\n        self.plane = torch.nn.Embedding(4, width)\n        self.fluid = torch.nn.Embedding(3, width)\n        self.fat = torch.nn.Embedding(3, width)\n        self.series = torch.nn.Embedding(4, width)\n        self.position = torch.nn.Linear(8, width)\n        self.input_norm = torch.nn.LayerNorm(width)\n        self.context = torch.nn.TransformerEncoderLayer(width, 4, dim_feedforward=512,\n                                                       dropout=0.1, batch_first=True, norm_first=True)\n        self.queries = torch.nn.Parameter(torch.randn(targets, width) * 0.02)\n        self.pool = torch.nn.MultiheadAttention(width, 4, dropout=0.1, batch_first=True)\n        self.output_norm = torch.nn.LayerNorm(width)\n        self.correction = torch.nn.Linear(width, 1)\n        # Small, nonzero weights: contextual queries/attention receive gradients\n        # from the first update, without swamping the retained local prediction.\n        torch.nn.init.normal_(self.correction.weight, std=0.005)\n        torch.nn.init.zeros_(self.correction.bias)\n        self.top_k_fraction = float(top_k_fraction)\n        if not 0 < self.top_k_fraction <= 1:\n            raise ValueError("Invalid top-k fraction")\n        self.to(memory_format=torch.channels_last)\n\n    def forward(self, batch, study_of_slice, studies, fixed_windows_per_study=None, fixed_window_valid=None):\n        if not isinstance(batch, WindowBatch) or batch.valid.shape != (studies, MAX_WINDOWS):\n            raise ValueError("Native-triplet WindowBatch required")\n        features = self.backbone(batch.images)\n        logits = self.head(features)\n        # Scatter using CPU-prepared indices: no boolean selection/nonzero CUDA\n        # synchronization per study and no encoder work on padded windows.\n        grouped = logits.new_zeros((studies * MAX_WINDOWS, logits.shape[-1])).index_copy(0, batch.padded_indices, logits)\n        grouped = grouped.view(studies, MAX_WINDOWS, -1).masked_fill(~batch.valid[..., None], -torch.inf)\n        max_k = max(1, math.ceil(MAX_WINDOWS * self.top_k_fraction))\n        values = grouped.topk(max_k, dim=1).values\n        counts = torch.ceil(batch.valid.sum(1) * self.top_k_fraction).long().clamp_min(1)\n        use = torch.arange(max_k, device=logits.device)[None, :, None] < counts[:, None, None]\n        local = values.masked_fill(~use, 0).sum(1) / counts[:, None]\n        meta = batch.metadata\n        discrete = meta[:, :4].long()\n        tokens = (self.projection(features) + self.plane(discrete[:, 0]) + self.fluid(discrete[:, 1])\n                  + self.fat(discrete[:, 2]) + self.series(discrete[:, 3]) + self.position(meta[:, 4:]))\n        tokens = self.input_norm(tokens)\n        grouped_tokens = tokens.new_zeros((studies * MAX_WINDOWS, tokens.shape[-1])).index_copy(0, batch.padded_indices, tokens)\n        grouped_tokens = grouped_tokens.view(studies, MAX_WINDOWS, -1)\n        padding = ~batch.valid\n        context = self.context(grouped_tokens, src_key_padding_mask=padding)\n        query = self.queries[None].expand(studies, -1, -1)\n        pooled, _ = self.pool(query, context, context, key_padding_mask=padding, need_weights=False)\n        delta = 0.1 * self.correction(self.output_norm(pooled)).squeeze(-1)\n        return local + delta\n'}
